const SUITS = { wand:{k:'완드',f:'열정과 행동'}, cup:{k:'컵',f:'감정과 관계'}, sword:{k:'소드',f:'생각과 갈등'}, penta:{k:'펜타클',f:'돈과 현실'} };
const IMG = {wand:'Wands', cup:'Cups', sword:'Swords', penta:'Pents'};

function buildDeck(){
  const d = MAJOR.map(m => ({ id:'M'+m.n, type:'major', num:m.n, name:m.k, en:m.e, img:'cards/M'+m.n+'.jpg',
    up:m.up, rv:m.rv, about:m.about, txt:{love:m.love, money:m.money, work:m.work, self:m.self} }));
  MINOR.forEach(m => d.push({ id:m.s+m.r, type:'minor', suit:m.s, rank:m.r, num:m.r, name:m.k, img:'cards/'+IMG[m.s]+m.r+'.jpg',
    up:m.up, rv:m.rv, about:m.about, txt:{love:m.love, money:m.money, work:m.work, self:m.self} }));
  return d;
}
const DECK = buildDeck();
